(() => {
  window.__bcSrcs = [...document.querySelectorAll('.banner-card img')].map((i) => i.src);
  const cards = [...document.querySelectorAll('.banner-card')];
  if (cards.length !== 4) throw new Error('cards=' + cards.length);
  const rerolls = [...document.querySelectorAll('.banner-card-reroll')];
  if (rerolls.length !== 4) throw new Error('randomizers=' + rerolls.length + ', need one per banner');
  if (document.querySelector('.banner-card-tag')) throw new Error('number tags still rendered');
  if (document.querySelector('.banners-head button')) throw new Error('a section-wide randomizer is still there');
  if (cards.some((c) => !c.querySelector('img'))) throw new Error('a card has no render');
  const title = document.querySelector('.stage-title').getBoundingClientRect();
  const head = document.querySelector('.banners-head').getBoundingClientRect();
  const g = document.querySelector('.banners-grid').getBoundingClientRect();
  const stage = document.querySelector('.stage');
  const cs = getComputedStyle(stage);
  const inner = stage.getBoundingClientRect().width - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
  const grid = document.querySelector('.grid').getBoundingClientRect();
  if (g.top < grid.bottom) throw new Error('banners overlap the profile grid');
  if (Math.abs(head.left - title.left) > 2) throw new Error('banners title off the stage edge');
  if (Math.abs(g.left - title.left) > 2) throw new Error('banners grid off the stage edge');
  if (Math.abs(g.width - inner) > 2) throw new Error('grid width ' + Math.round(g.width) + ' vs stage ' + Math.round(inner));
  const ratios = cards.map((c) => { const r = c.getBoundingClientRect(); return r.width / r.height; });
  const bad = ratios.find((r) => Math.abs(r - 1546 / 423) > 0.02);
  if (bad) throw new Error('card aspect ' + bad.toFixed(3));
  if (new Set(cards.map((c) => Math.round(c.getBoundingClientRect().top))).size !== 1) throw new Error('cards wrapped onto two rows');
  return 'section ok: 4 cards, 4 randomizers, aspect ' + ratios[0].toFixed(3);
})()

(() => {
  const before = window.__bcSrcs;
  const now = [...document.querySelectorAll('.banner-card img')].map((i) => i.src);
  if (now.length !== before.length) throw new Error('card count changed');
  const changed = now.map((src, i) => src !== before[i]);
  const count = changed.filter(Boolean).length;
  if (!changed[1]) throw new Error('card 2 did not change its look');
  if (count !== 1) throw new Error(count + ' cards re-rolled, expected 1 — the randomizers are not separate');
  throw new Error('per-banner reroll isolated to card 2, other 3 untouched');
})()

(() => {
  const L = window.__bcBannerLayout;
  if (!L) throw new Error('no layout probe');
  if (L.order.join('>') !== 'bg>left>right>text') throw new Error('paint order ' + L.order.join('>'));
  if (Math.abs(L.width / L.height - 16 / 9) > 0.01) throw new Error('frame aspect ' + (L.width / L.height).toFixed(3));
  if (Math.abs(L.strip.x + L.strip.w / 2 - L.width / 2) > 2) throw new Error('strip off centre');
  if (Math.abs(L.text.x + L.text.w / 2 - L.width / 2) > 2) throw new Error('wordmark box off centre');
  if (L.left.x < L.strip.x + 4) throw new Error('left figure runs over the strip edge');
  if (L.right.x + L.right.w > L.strip.x + L.strip.w - 4) throw new Error('right figure runs over the strip edge');
  if (L.text.x < L.left.x + L.left.w - 1) throw new Error('wordmark box overlaps the left bust');
  if (L.text.x + L.text.w > L.right.x + 1) throw new Error('wordmark box overlaps the right bust');

  const img = document.querySelector('.download-preview.is-banner img');
  const c = document.createElement('canvas');
  c.width = img.naturalWidth;
  c.height = img.naturalHeight;
  const x = c.getContext('2d');
  x.drawImage(img, 0, 0);
  const W = c.width;
  const H = c.height;
  const px = (X, Y) => { const d = x.getImageData(X, Y, 1, 1).data; return d[0] + ',' + d[1] + ',' + d[2]; };
  const outside = [px(4, 4), px(W - 5, 4), px(4, H - 5), px(W - 5, H - 5), px(Math.round(W / 2), 6), px(Math.round(W / 2), H - 6)];
  if (!outside.every((v) => v === outside[0])) throw new Error('outside strip not flat: ' + outside.join(' | '));
  const bg = outside[0];
  const bleed = [];
  for (let y = Math.round(L.left.y) + 30; y < Math.round(L.left.y + L.left.h) - 6; y += 24) {
    bleed.push(px(Math.round(L.strip.x) + 2, y), px(Math.round(L.strip.x + L.strip.w) - 3, y));
  }
  const dirty = bleed.find((v) => v !== bg);
  if (dirty) throw new Error('a figure is still sliced by the strip edge: found ' + dirty + ', bg ' + bg);
  const gapFrom = Math.round(L.left.x + L.left.w);
  const gapTo = Math.round(L.right.x);
  const cols = new Int32Array(W);
  for (let Y = Math.round(L.strip.y); Y < Math.round(L.strip.y + L.strip.h); Y += 1) {
    for (let X = gapFrom; X <= gapTo; X += 1) {
      const d = x.getImageData(X, Y, 1, 1).data;
      if (d[0] > 200 && d[1] > 200 && d[2] < 110) cols[X] += 1;
    }
  }
  let ink = 0;
  let minX = -1;
  let maxX = -1;
  for (let X = gapFrom; X <= gapTo; X += 1) {
    ink += cols[X];
    if (cols[X] > 0) { if (minX < 0) minX = X; maxX = X; }
  }
  if (ink < 200 || minX < 0) throw new Error('wordmark missing between the busts, ink px=' + ink);
  if (minX <= gapFrom + 1 || maxX >= gapTo - 1) throw new Error('wordmark runs into a figure: ' + minX + '..' + maxX + ' gap ' + gapFrom + '..' + gapTo);
  const drift = Math.round((minX + maxX) / 2 - W / 2);
  if (Math.abs(drift) > 8) throw new Error('wordmark off centre by ' + drift + 'px (' + minX + '..' + maxX + ' of ' + W + ')');
  const ratio = (maxX - minX) / W;
  if (ratio < 0.15 || ratio > 0.22) throw new Error('wordmark width ' + (ratio * 100).toFixed(1) + '% of the frame, wanted 15-22%');

  throw new Error('frame=' + W + 'x' + H + ' bg=' + bg + ' flat=yes edge-clean=yes ink=' + ink + ' inkW=' + (maxX - minX) + ' drift=' + drift + 'px width=' + (ratio * 100).toFixed(1) + '% font=' + L.font + ' rig=' + L.rig + ' pair=' + L.pair.join('+'));
})()

(() => {
  const L = window.__bcBannerLayout;
  if (L.width !== 2560) throw new Error('export width ' + L.width);
  if (L.height !== 1440) throw new Error('export height ' + L.height);
  if (L.bytes < 30000) throw new Error('export too small: ' + L.bytes);
  if (L.bytes > 6000000) throw new Error('over the YouTube cap: ' + L.bytes);
  const ratio = L.text.w / L.width;
  if (Math.abs(ratio - 0.2039) > 0.002) throw new Error('wordmark box is not the same fraction of the frame as the preview: ' + ratio.toFixed(4));
  if (Math.abs(L.text.x + L.text.w / 2 - L.width / 2) > 2) throw new Error('wordmark box off centre in the export');
  if (Math.abs(L.strip.w / L.width - 1546 / 2560) > 0.001) throw new Error('strip is not the same fraction of the frame');
  throw new Error('export=' + L.width + 'x' + L.height + ' bytes=' + L.bytes + ' ms=' + L.ms + ' textBox=' + (ratio * 100).toFixed(2) + '% of frame (same as preview)');
})()
